/** Adds the Arabic title (`title.ar`) from `./ar`. */
export const duas: Dua[] = rawDuas.map((d) => ({ ...d, title: { ...d.title, ar: duaTitleAr[d.slug] ?? d.title.ar } }))
export const duaBySlug = (slug: string) => duas.find((d) => d.slug === slug)
